## solutions

#### depth first (recursive)

```cpp
#include <limits>
#include <algorithm>

int treeMinValue(Node* root) {
  if (root == nullptr) {
    return std::numeric_limits<int>::max();
  }

  return std::min({ root->val, treeMinValue(root->left), treeMinValue(root->right) });
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)

#### breadth first (iterative)

```cpp
#include <limits>
#include <queue>

int treeMinValue(Node* root) {
  int min = std::numeric_limits<int>::max();
  std::queue<Node*> queue;
  queue.push(root);
  while (queue.size() > 0) {
    Node* current = queue.front();
    queue.pop();
    if (current->val < min) {
      min = current->val;
    } 

    if (current->left) {
      queue.push(current->left);
    }
    if (current->right) {
      queue.push(current->right);
    }
  }
  return min;
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)
